SELECT p.id AS position_id, w.id AS wallet_trade_id, w.symbol, w.side, w.quantity, w.price_usdt, w.decision_price_usdt, TIMESTAMPADD(MICROSECOND, CAST(ROUND(UNIX_TIMESTAMP(w.execution_price_observed_at)*1000000) AS SIGNED), '1970-01-01 00:00:00') AS price_observed_utc, TIMESTAMPADD(MICROSECOND, CAST(ROUND(UNIX_TIMESTAMP(w.executed_at)*1000000) AS SIGNED), '1970-01-01 00:00:00') AS executed_utc, ROUND(UNIX_TIMESTAMP(w.executed_at)-UNIX_TIMESTAMP(w.execution_price_observed_at),3) AS price_age_s, w.gross_amount_usdt, w.fee_usdt, w.net_amount_usdt, w.cost_basis_usdt, w.realized_pnl_usdt, w.realized_pnl_percent, w.execution_type, w.execution_reason, w.execution_key, w.signal_id, w.position_analysis_id FROM paper_position p JOIN wallet_trade w ON w.symbol = p.symbol AND w.executed_at BETWEEN TIMESTAMPADD(SECOND,-120,p.opened_at) AND TIMESTAMPADD(SECOND,120,p.closed_at) WHERE p.id IN (182,172,162,158,143,137) ORDER BY p.id, w.executed_at;